const studyId = $json.study_id ?? 'study_test_001';
const outputMode = $json.output_mode ?? 'final_insights';
const supabaseUrl = $env.SUPABASE_URL || 'https://SET_SUPABASE_URL';
const supabaseKey = $env.SUPABASE_SERVICE_ROLE_KEY || 'SET_SUPABASE_SERVICE_ROLE_KEY';
const headers = { 'apikey': supabaseKey, 'Authorization': 'Bearer ' + supabaseKey, 'Content-Type': 'application/json' };
const studyRes = await this.helpers.httpRequest({ method: 'GET', url: supabaseUrl + '/rest/v1/BE_studies?study_id=eq.' + encodeURIComponent(studyId) + '&limit=1', headers });
const study = Array.isArray(studyRes) ? studyRes[0] : null;
if (!study) throw new Error('Study not found: ' + studyId);
const detectionsRes = await this.helpers.httpRequest({ method: 'GET', url: supabaseUrl + '/rest/v1/BE_behavior_detections?study_id=eq.' + encodeURIComponent(studyId) + '&order=timestamp.asc&limit=1000', headers });
const detections = Array.isArray(detectionsRes) ? detectionsRes : [];
return [{ json: { study_id: studyId, output_mode: outputMode, study_plan: study.study_plan ?? {}, graph_plan: study.graph_plan ?? {}, instructions: study.metadata?.instructions ?? '', detection_log: detections.map(d => ({ study_id: d.study_id, image_id: d.image_id, timestamp: d.timestamp, zone_id: d.zone_id, detected_behaviors: d.detected_behaviors ?? [], confidence_scores: d.confidence_scores ?? {}, notes: d.notes ?? '', model_version: d.model_version ?? '', parse_error: null })) } }];

const body = $json;
const errors = [];
let rawText = '';
try { rawText = body.choices[0].message.content; } catch(e) { errors.push('failed_to_extract_content'); }
let cleaned = rawText.trim();
if (cleaned.startsWith('```')) { cleaned = cleaned.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '').trim(); }
let parsed = {};
try { parsed = JSON.parse(cleaned); } catch(e) { errors.push('json_parse_failed'); }
for (const field of ["study_id","output_mode","dashboard_summary","charts","tables","insights","recommendations"]) {
  if (!(field in parsed)) errors.push('missing_' + field);
}
return [{ json: { raw_ai_output: rawText, parsed_output: parsed, validation_passed: errors.length === 0, validation_errors: errors } }];

const item = $input.first().json;
const output = item.output ?? item.text ?? item.response ?? item.data ?? item;
let parsed = output;
const errors = [];
if (typeof parsed === 'string') { try { parsed = JSON.parse(parsed); } catch (error) { errors.push('json_parse_failed'); } }
if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) { errors.push('payload_not_object'); parsed = {}; }
for (const field of ["study_id","output_mode","dashboard_summary","charts","tables","insights","recommendations"]) {
  if (!(field in parsed)) errors.push('missing_' + field);
}
return [{ json: { raw_ai_output: output, parsed_output: parsed, validation_passed: errors.length === 0, validation_errors: errors } }];
